/**
 * Policy Clause Templates — Supplier Security (p42-p43)
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 *
 * Delegation strategy:
 * - p42 owns: contractual/operational supplier security (access, audits, contracts, onboarding, subcontractors, SBOM)
 * - p43 owns: strategic third-party risk management (methodology, dashboards, concentration risk, geopolitical, DORA)
 * - Cross-references prevent duplication between p42 and p43
 */
import type { PolicyClause } from "../policyClauseTemplates";

export const supplierSecurityClauses: Record<string, PolicyClause[]> = {
  p42: [
    { id: "p42-c00", title: "Zweck und Geltungsbereich der Lieferantensicherheitsrichtlinie", titleEn: "Purpose & Scope of Supplier Security Policy", description: "Diese Richtlinie definiert die operativen Sicherheitsanforderungen an Lieferanten, Dienstleister und Partner der Organisation. Sie gilt für alle Drittanbieterbeziehungen mit Zugang zu Informationen, Systemen oder Daten der Organisation und stellt die Einhaltung von NIS2 Art.21(2)(d) sicher. Das strategische Risikomanagement-Framework wird in p43 definiert.", descriptionEn: "This policy defines operational security requirements for suppliers, service providers, and partners. It applies to all third-party relationships with access to organisation information, systems, or data, ensuring NIS2 Art.21(2)(d) compliance. The strategic risk management framework is defined in p43.", reason: "Lieferkettenangriffe nehmen drastisch zu. Ohne umfassende Lieferantensicherheitsrichtlinie ist die eigene Sicherheit gefährdet.", reasonEn: "Supply chain attacks are increasing drastically. Without comprehensive supplier security policy, own security is jeopardised.", whenRequired: "Immer erforderlich als NIS2-Anforderung.", whenRequiredEn: "Always required as NIS2 requirement.", sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.19-5.22", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC"] },
    { id: "p42-c01", title: "Lieferantenbewertung, Due Diligence und Zertifizierungen", titleEn: "Supplier Assessment, Due Diligence & Certifications", description: "Vor der Beauftragung eines neuen Lieferanten muss eine Sicherheitsbewertung durchgeführt werden. Die Bewertung muss Sicherheitsorganisation, Zertifizierungen (ISO 27001, SOC 2 Type II, BSI C5), technische Schutzmaßnahmen, Vorfallmanagement-Fähigkeiten, Datenschutzkonformität und finanzielle Stabilität umfassen. Die Intensität der Due Diligence richtet sich nach der Risikoklassifizierung (siehe p43-c01). Der Zertifizierungsstatus muss bei der Erstbewertung und bei jeder Neubewertung überprüft werden.", descriptionEn: "Before engaging a new supplier, a security assessment must be conducted covering security organisation, certifications (ISO 27001, SOC 2 Type II, BSI C5), technical measures, incident management capabilities, data protection compliance, and financial stability. The intensity of due diligence depends on risk classification (see p43-c01). Certification status must be verified during initial assessment and every reassessment.", reason: "Wir können unsere eigene Sicherheit nicht gewährleisten, wenn Lieferanten unsicher sind. Zertifizierungen bieten unabhängige Bestätigung.", reasonEn: "We cannot ensure our own security if suppliers are insecure. Certifications provide independent confirmation.", whenRequired: "Erforderlich vor jeder neuen Lieferantenbeziehung.", whenRequiredEn: "Required before every new supplier relationship.", sources: ["ISO 27001:2022 A.5.19-5.21", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1", "BSI C5:2020", "NIST CSF 2.0 GV.SC"] },
    { id: "p42-c02", title: "Vertragliche Sicherheitsanforderungen", titleEn: "Contractual Security Requirements", description: "Verträge mit Lieferanten müssen verbindliche Sicherheitsklauseln enthalten: NDA, Sicherheitsanforderungen, Audit-Rechte, Vorfallmeldepflichten, SLAs für Sicherheit und Verfügbarkeit, Regelungen für Unterauftragnehmer und Vertragsbeendigung. Datenschutzregelungen (DSGVO Art.28) und Auftragsverarbeitungsverträge werden über p43-c12 koordiniert.", descriptionEn: "Contracts with suppliers must contain binding security clauses: NDA, security requirements, audit rights, incident notification obligations, SLAs for security and availability, subcontractor provisions, and contract termination terms. Data protection provisions (GDPR Art.28) and data processing agreements are coordinated via p43-c12.", reason: "Ohne vertragliche Vereinbarungen hat die Organisation keine Handhabe, Sicherheitsanforderungen durchzusetzen.", reasonEn: "Without contractual agreements, we have no means to enforce security requirements.", whenRequired: "Erforderlich für alle Lieferantenverträge mit IT-Bezug.", whenRequiredEn: "Required for all supplier contracts with IT relevance.", sources: ["ISO 27001:2022 A.5.20", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p42-c03", title: "Laufende Lieferantenüberwachung und KPI-Management", titleEn: "Ongoing Supplier Monitoring & KPI Management", description: "Die Sicherheitslage von Lieferanten muss während der gesamten Vertragslaufzeit überwacht werden: jährliche Sicherheitsbewertungen, SLA-Prüfung, Auswertung von Vorfällen beim Lieferanten, Tracking von Audit-Feststellungen und Neubewertung bei wesentlichen Änderungen. Die Sicherheitsperformance muss anhand definierter KPIs gemessen werden: Sicherheitsvorfälle, Reaktionszeiten, Patch-Compliance, SLA-Einhaltung. Leistungsberichte müssen quartalsweise erstellt werden. Eskalationsmaßnahmen bis zur Vertragsbeendigung müssen vorgesehen sein. Für strategische Risikoindikatoren und automatisierte Überwachung siehe p43-c04.", descriptionEn: "Supplier security posture must be monitored throughout the contract: annual security assessments, SLA verification, evaluation of supplier incidents, tracking audit findings, and reassessment upon significant changes. Security performance must be measured using defined KPIs: security incidents, response times, patch compliance, SLA adherence. Performance reports must be created quarterly. Escalation measures up to contract termination must be provided. For strategic risk indicators and automated monitoring see p43-c04.", reason: "Die Sicherheitslage eines Lieferanten kann sich verschlechtern. Ohne Überwachung und KPIs bleibt die Bewertung subjektiv.", reasonEn: "A supplier's security posture can deteriorate. Without monitoring and KPIs, assessment remains subjective.", whenRequired: "Erforderlich für alle aktiven Lieferantenbeziehungen.", whenRequiredEn: "Required for all active supplier relationships.", sources: ["ISO 27001:2022 A.5.22", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC", "ITIL 4"] },
    { id: "p42-c04", title: "Lieferanten-Audit-Rechte", titleEn: "Supplier Audit Rights", description: "Verträge müssen der Organisation das Recht einräumen, die Sicherheitsmaßnahmen des Lieferanten zu überprüfen. Audit-Rechte umfassen: Vor-Ort-Inspektionen, Einsicht in Audit-Berichte (SOC 2, ISO 27001), Prüfung technischer Maßnahmen und Befragung von Schlüsselpersonal. Die Häufigkeit richtet sich nach der Risikoklassifizierung (p43-c01).", descriptionEn: "Contracts must grant the organisation the right to verify supplier security measures. Audit rights include: on-site inspections, review of audit reports (SOC 2, ISO 27001), examination of technical measures, and interviews with key personnel. Frequency depends on risk classification (p43-c01).", reason: "Vertragliche Zusicherungen ohne Überprüfungsmöglichkeit bieten keine Sicherheit.", reasonEn: "Contractual assurances without verification capability provide no security.", whenRequired: "Erforderlich für alle kritischen und hochriskanten Lieferanten.", whenRequiredEn: "Required for all critical and high-risk suppliers.", sources: ["ISO 27001:2022 A.5.22", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC"] },
    { id: "p42-c05", title: "IKT-Lieferkettensicherheit und SBOM", titleEn: "ICT Supply Chain Security & SBOM", description: "Für IKT-Produkte und -Dienstleistungen müssen besondere Sicherheitsanforderungen gelten: Prüfung auf Manipulationssicherheit, Bewertung der Herkunft (vertrauenswürdige Hersteller), Integritätsprüfung bei Auslieferung und sichere Lieferkanäle. Für eingekaufte Software muss eine Software Bill of Materials (SBOM) angefordert werden. Die SBOM muss alle Komponenten einschließlich Open-Source-Bibliotheken und deren Versionen auflisten. Bekannte Schwachstellen in Komponenten müssen identifiziert und bewertet werden. Lieferanten müssen sich verpflichten, über neue Schwachstellen zeitnah zu informieren.", descriptionEn: "For ICT products and services, special security requirements must apply: verification of tamper resistance, assessment of origin (trusted manufacturers), integrity verification upon delivery, and secure delivery channels. For purchased software, a Software Bill of Materials (SBOM) must be requested listing all components including open-source libraries and versions. Known vulnerabilities must be identified and assessed. Suppliers must commit to promptly informing about new vulnerabilities.", reason: "NIS2 fordert explizit die Sicherheit der IKT-Lieferkette. Software-Supply-Chain-Angriffe (z.B. SolarWinds, Log4j) zeigen die Notwendigkeit von Transparenz.", reasonEn: "NIS2 explicitly requires ICT supply chain security. Software supply chain attacks (e.g., SolarWinds, Log4j) demonstrate the need for transparency.", whenRequired: "Erforderlich für alle IKT-Beschaffungen.", whenRequiredEn: "Required for all ICT procurements.", sources: ["NIS2 Art.21(2)(d), Art.22", "ISO 27001:2022 A.5.21", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC", "CRA (Cyber Resilience Act)"] },
    { id: "p42-c06", title: "Cloud-Dienstleister-Sicherheit", titleEn: "Cloud Service Provider Security", description: "Für Cloud-Dienstleister gelten besondere Anforderungen: BSI C5-Testat oder vergleichbare Zertifizierung, Datenresidenz innerhalb des EWR, Verschlüsselung mit kundenseitiger Schlüsselverwaltung, transparente Subprozessor-Kette, Notfallpläne für Anbieterwechsel (Exit-Strategie) und Einhaltung der DSGVO-Anforderungen an Auftragsverarbeitung.", descriptionEn: "Special requirements apply for cloud service providers: BSI C5 attestation or comparable certification, data residency within EEA, encryption with customer-managed keys, transparent sub-processor chain, contingency plans for provider change (exit strategy), and GDPR data processing compliance.", reason: "Cloud-Dienste sind besonders kritisch, da wir die physische Kontrolle über unsere Daten abgeben.", reasonEn: "Cloud services are particularly critical as we relinquish physical control over our data.", whenRequired: "Erforderlich für alle Cloud-Dienstleister.", whenRequiredEn: "Required for all cloud service providers.", sources: ["BSI C5:2020", "ISO 27001:2022 A.5.23", "DSGVO Art.28", "NIS2 Art.21(2)(d)"] },
    { id: "p42-c07", title: "Unterauftragnehmer- und Vierte-Partei-Management", titleEn: "Subcontractor & Fourth-Party Management", description: "Wir müssen über die Nutzung von Unterauftragnehmern durch unsere Lieferanten informiert sein. Lieferanten dürfen Unterauftragnehmer nur mit vorheriger Genehmigung einsetzen. Sicherheitsanforderungen müssen vertraglich an Unterauftragnehmer weitergegeben werden. Die Kette der Unterbeauftragung muss begrenzt und überwacht werden. Kritische Unterauftragnehmer (vierte Parteien) müssen identifiziert und deren Risiken bewertet werden. Vertragliche Transparenzpflichten über Unterbeauftragungsketten müssen vereinbart werden.", descriptionEn: "We must be informed about subcontractor use by our suppliers. Suppliers may only engage subcontractors with prior approval. Security requirements must be contractually passed to subcontractors. The subcontracting chain must be limited and monitored. Critical subcontractors (fourth parties) must be identified and their risks assessed. Contractual transparency obligations about subcontracting chains must be agreed.", reason: "Risiken können sich durch intransparente Unterbeauftragung unkontrolliert verbreiten. Viele Supply-Chain-Angriffe erfolgen über Subunternehmer.", reasonEn: "Risks can spread uncontrollably through non-transparent subcontracting. Many supply chain attacks occur through subcontractors.", whenRequired: "Erforderlich für alle Lieferantenverträge mit Unterauftragnehmer-Möglichkeit.", whenRequiredEn: "Required for all supplier contracts with subcontractor possibility.", sources: ["DSGVO Art.28(2)", "ISO 27001:2022 A.5.19, A.5.21", "BSI IT-Grundschutz OPS.2.1", "NIS2 Art.21(2)(d)", "NIST CSF 2.0 GV.SC"] },
    { id: "p42-c08", title: "Lieferanten-Vorfallkoordination", titleEn: "Supplier Incident Coordination", description: "Verfahren für die koordinierte Vorfallbehandlung mit Lieferanten müssen definiert sein: Meldepflichten und -fristen für Sicherheitsvorfälle, Kontaktpunkte auf beiden Seiten, gemeinsame Untersuchungsverfahren, Informationsaustausch über Bedrohungsindikatoren und Verfahren für den Fall einer Kompromittierung des Lieferanten.", descriptionEn: "Procedures for coordinated incident handling with suppliers must be defined: notification obligations and deadlines for security incidents, contact points on both sides, joint investigation procedures, threat indicator sharing, and procedures for supplier compromise.", reason: "Ein Vorfall beim Lieferanten betrifft häufig auch die Organisation. Ohne vordefinierte Koordinationsverfahren verzögert sich die Reaktion.", reasonEn: "An incident at the supplier frequently also affects the organisation. Without pre-defined coordination procedures, response is delayed.", whenRequired: "Erforderlich für alle kritischen Lieferanten.", whenRequiredEn: "Required for all critical suppliers.", sources: ["NIS2 Art.23", "ISO 27001:2022 A.5.24", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p42-c09", title: "Zugangskontrolle, Fernzugriff und Protokollierung für Lieferanten", titleEn: "Supplier Access Control, Remote Access & Logging", description: "Der Zugang von Lieferanten zu Systemen und Daten muss streng kontrolliert werden: dedizierte Accounts (keine geteilten Zugänge), Least-Privilege-Prinzip, zeitliche Begrenzung, MFA-Pflicht, Protokollierung aller Aktivitäten und regelmäßige Überprüfung aktiver Zugänge. Fernzugriff muss über gesicherte VPN-Verbindungen mit MFA erfolgen. Sitzungen müssen zeitlich begrenzt, überwacht und aufgezeichnet werden. Just-in-Time-Zugang muss bevorzugt werden. Privilegierter Zugang muss über Privileged Access Management (PAM) kontrolliert und sitzungsbasiert aufgezeichnet werden. Anomale Aktivitäten müssen automatisch erkannt und eskaliert werden. Zugang muss bei Vertragsende sofort entzogen werden.", descriptionEn: "Supplier access to systems and data must be strictly controlled: dedicated accounts (no shared access), least privilege principle, time limitation, MFA requirement, logging of all activities, and regular review of active access. Remote access must be via secured VPN connections with MFA. Sessions must be time-limited, monitored, and recorded. Just-in-time access must be preferred. Privileged access must be controlled through PAM and session-recorded. Anomalous activities must be automatically detected and escalated. Access must be revoked immediately upon contract end.", reason: "Unkontrollierter Lieferantenzugang ist einer der häufigsten Angriffsvektoren. Strenge Zugangs- und Protokollierungskontrolle minimiert das Risiko.", reasonEn: "Uncontrolled supplier access is one of the most common attack vectors. Strict access and logging control minimises the risk.", whenRequired: "Erforderlich für alle Lieferanten mit Systemzugang.", whenRequiredEn: "Required for all suppliers with system access.", sources: ["ISO 27001:2022 A.5.18, A.8.3, A.8.15-8.16, A.8.20", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 PR.AA, DE.CM"] },
    { id: "p42-c10", title: "Lieferantenregister und Vertragsdatenbank", titleEn: "Supplier Register & Contract Database", description: "Wir müssen ein zentrales Lieferantenregister führen, das alle Lieferanten mit IT-Bezug dokumentiert: Name und Kontaktdaten, Risikoklassifizierung (p43-c01), vertragliche Vereinbarungen, Zertifizierungsstatus, Bewertungsergebnisse, letzte Überprüfung und nächste geplante Überprüfung. Alle Verträge müssen zentral verwaltet werden mit Vertragslaufzeiten, Kündigungsfristen, Sicherheitsklauseln und SLAs. Automatische Benachrichtigungen bei Vertragsverlängerungen und -abläufen müssen konfiguriert sein.", descriptionEn: "We must maintain a central supplier register documenting all IT-relevant suppliers: name and contact details, risk classification (p43-c01), contractual agreements, certification status, assessment results, last review, and next planned review. All contracts must be centrally managed with contract terms, notice periods, security clauses, and SLAs. Automatic notifications for contract renewals and expirations must be configured.", reason: "Ohne zentrales Register und Vertragsdatenbank verliert die Organisation den Überblick über Lieferantenbeziehungen.", reasonEn: "Without a central register and contract database, we lose oversight of supplier relationships.", whenRequired: "Immer erforderlich als Grundlage des Lieferantenmanagements.", whenRequiredEn: "Always required as the foundation of supplier management.", sources: ["ISO 27001:2022 A.5.19-5.20", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC"] },
    { id: "p42-c11", title: "Exit-Strategie und Vertragsbeendigung", titleEn: "Exit Strategy & Contract Termination", description: "Für jeden kritischen Lieferanten muss eine Exit-Strategie definiert sein: Datenrückgabe und -löschung, Migrationsprozess, Übergangszeitraum, alternative Lieferanten, Sicherstellung der Geschäftskontinuität während des Wechsels und Entzug aller Zugänge. Die Exit-Strategie muss vor Vertragsschluss definiert und vertraglich verankert werden.", descriptionEn: "An exit strategy must be defined for every critical supplier: data return and deletion, migration process, transition period, alternative suppliers, ensuring business continuity during the switch, and revocation of all access. The exit strategy must be defined before contract conclusion and contractually anchored.", reason: "Ohne Exit-Strategie entsteht Abhängigkeit (Vendor Lock-in). Bei Sicherheitsproblemen muss ein geordneter Wechsel möglich sein.", reasonEn: "Without an exit strategy, dependency (vendor lock-in) arises. In case of security issues, an orderly switch must be possible.", whenRequired: "Erforderlich für alle kritischen Lieferanten.", whenRequiredEn: "Required for all critical suppliers.", sources: ["ISO 27001:2022 A.5.20", "BSI IT-Grundschutz OPS.2.1", "BSI C5:2020"] },
    { id: "p42-c12", title: "Lieferanten-Onboarding und -Offboarding", titleEn: "Supplier Onboarding & Offboarding", description: "Standardisierte Prozesse für Onboarding und Offboarding müssen definiert sein. Onboarding: Sicherheitsbewertung (p42-c01), Vertragsprüfung (p42-c02), Zugangsprovisionierung (p42-c09), Schulung über Sicherheitsanforderungen, initiale Überwachungsperiode. Offboarding: sofortiger Entzug aller Zugänge, Rückgabe aller Vermögenswerte und Daten, Löschungsbestätigung, Deaktivierung aller VPN- und Remote-Zugänge, Dokumentation der Vertragsbeendigung.", descriptionEn: "Standardised onboarding and offboarding processes must be defined. Onboarding: security assessment (p42-c01), contract review (p42-c02), access provisioning (p42-c09), training on security requirements, initial monitoring period. Offboarding: immediate revocation of all access, return of all assets and data, deletion confirmation, deactivation of all VPN and remote access, documentation of contract termination.", reason: "Ohne strukturierte Prozesse werden kritische Sicherheitsschritte übersehen. Nicht entzogene Zugänge stellen ein kritisches Risiko dar.", reasonEn: "Without structured processes, critical security steps are overlooked. Non-revoked access poses a critical risk.", whenRequired: "Erforderlich für alle Lieferanten.", whenRequiredEn: "Required for all suppliers.", sources: ["ISO 27001:2022 A.5.19-5.20, A.6.5", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 PR.AA"] },
    { id: "p42-c13", title: "Lieferantenschulungen und -sensibilisierung", titleEn: "Supplier Training & Awareness", description: "Lieferanten mit Zugang zu Systemen oder Daten der Organisation müssen über die geltenden Sicherheitsrichtlinien informiert und bei Bedarf geschult werden. Lieferantenmitarbeiter müssen die Acceptable Use Policy und relevante Sicherheitsanforderungen kennen und akzeptieren. Die Bestätigung muss dokumentiert werden.", descriptionEn: "Suppliers with access to organisation systems or data must be informed about applicable security policies and trained as needed. Supplier employees must know and accept the Acceptable Use Policy and relevant security requirements. Confirmation must be documented.", reason: "Lieferanten, die die Sicherheitsrichtlinien nicht kennen, können unbeabsichtigt Sicherheitsverstöße verursachen.", reasonEn: "Suppliers unaware of security policies can unintentionally cause security violations.", whenRequired: "Erforderlich für alle Lieferanten mit direktem Systemzugang.", whenRequiredEn: "Required for all suppliers with direct system access.", sources: ["ISO 27001:2022 A.6.6", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p42-c14", title: "Kommunikation und Eskalation", titleEn: "Communication & Escalation", description: "Klare Kommunikationswege und Eskalationspfade mit allen Lieferanten müssen definiert sein. Operative, taktische und strategische Ansprechpartner müssen benannt werden.", descriptionEn: "Clear communication channels and escalation paths must be defined with all suppliers. Operational, tactical, and strategic contacts must be named.", reason: "Ohne definierte Kommunikationswege werden Probleme nicht rechtzeitig eskaliert.", reasonEn: "Without defined communication channels, problems are not escalated in time.", whenRequired: "Erforderlich für alle aktiven Lieferantenbeziehungen.", whenRequiredEn: "Required for all active supplier relationships.", sources: ["ISO 27001:2022 A.5.20", "BSI IT-Grundschutz OPS.2.1", "ITIL 4"] },
    { id: "p42-c15", title: "Sicherheitsanforderungen für API-Integrationen", titleEn: "Security Requirements for API Integrations", description: "API-basierte Integrationen mit Lieferanten müssen besondere Sicherheitsanforderungen erfüllen: API-Key-Management, OAuth 2.0/OIDC-Authentifizierung, Rate-Limiting, Input-Validation, verschlüsselte Kommunikation und Monitoring. API-Zugriffe müssen auf minimal notwendige Berechtigungen beschränkt werden.", descriptionEn: "API-based integrations with suppliers must meet special security requirements: API key management, OAuth 2.0/OIDC authentication, rate limiting, input validation, encrypted communication, and monitoring. API access must be restricted to minimally necessary permissions.", reason: "Unsichere APIs sind ein häufiger Angriffsvektor. Jede API-Integration erweitert die Angriffsfläche.", reasonEn: "Insecure APIs are a common attack vector. Every API integration expands the attack surface.", whenRequired: "Erforderlich für alle API-Integrationen.", whenRequiredEn: "Required for all API integrations.", sources: ["ISO 27001:2022 A.8.24-8.26", "OWASP API Security Top 10", "NIST CSF 2.0 PR.DS"] },
    { id: "p42-c16", title: "Überprüfung der Lieferantensicherheitsrichtlinie", titleEn: "Review of Supplier Security Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Neue regulatorische Anforderungen und Erfahrungen aus Lieferantenvorfällen müssen berücksichtigt werden. Die Überprüfung muss mit dem Third-Party-Risikomanagement (p43-c16) koordiniert werden.", descriptionEn: "This policy must be reviewed and updated at least annually. New regulatory requirements and experiences from supplier incidents must be considered. The review must be coordinated with third-party risk management (p43-c16).", reason: "Bedrohungslandschaft und regulatorische Anforderungen ändern sich ständig.", reasonEn: "Threat landscape and regulatory requirements are constantly changing.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §10.1-10.2", "NIS2 Art.21", "BSI IT-Grundschutz OPS.2.1"] },
  ],

  p43: [
    { id: "p43-c00", title: "Zweck und Geltungsbereich des Third-Party-Risikomanagements", titleEn: "Purpose & Scope of Third-Party Risk Management", description: "Diese Richtlinie definiert den systematischen Umgang mit Risiken aus Drittanbieterbeziehungen. Sie ergänzt die Lieferantensicherheitsrichtlinie (p42) um ein risikobasiertes Management-Framework und gilt für alle externen Parteien, die Zugang zu Informationen oder Systemen der Organisation haben oder Dienste erbringen. Operative Anforderungen (Verträge, Zugang, Audits) werden in p42 definiert.", descriptionEn: "This policy defines the systematic management of risks from third-party relationships. It complements the supplier security policy (p42) with a risk-based management framework and applies to all external parties with access to organisation information or systems, or providing services. Operational requirements (contracts, access, audits) are defined in p42.", reason: "Systematisches Risikomanagement für Drittanbieter ist eine NIS2-Kernanforderung und essentiell für die Gesamtsicherheit.", reasonEn: "Systematic third-party risk management is a core NIS2 requirement and essential for overall security.", whenRequired: "Immer erforderlich als NIS2-Anforderung.", whenRequiredEn: "Always required as NIS2 requirement.", sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.19", "NIST CSF 2.0 GV.SC"] },
    { id: "p43-c01", title: "Risikobewertungsmethodik und Risikoklassifizierung", titleEn: "Risk Assessment Methodology & Risk Classification", description: "Wir müssen eine standardisierte Methodik für die Risikobewertung und -klassifizierung von Drittanbietern definieren. Bewertungskriterien umfassen: Art und Umfang des Zugangs, Sensitivität der verarbeiteten Daten, Ersetzbarkeit des Drittanbieters, geographische Risiken und Compliance-Status. Lieferanten müssen in Risikoklassen eingeteilt werden: Kritisch (Zugang zu kritischen Systemen/Daten), Hoch (Zugang zu vertraulichen Daten), Mittel (Zugang zu internen Daten) und Niedrig (kein IT-Zugang). Die Bewertung muss quantifizierbar und vergleichbar sein. Die Intensität der Due Diligence (p42-c01) und Überwachung (p42-c03) muss der Risikoklasse entsprechen.", descriptionEn: "We must define a standardised methodology for risk assessment and classification of third parties. Assessment criteria include: type and extent of access, sensitivity of processed data, replaceability, geographical risks, and compliance status. Suppliers must be categorised into risk classes: Critical, High, Medium, and Low. Assessment must be quantifiable and comparable. The intensity of due diligence (p42-c01) and monitoring (p42-c03) must match the risk class.", reason: "Ohne standardisierte Methodik werden Drittanbieterrisiken inkonsistent bewertet. Risikobasierte Klassifizierung ermöglicht effiziente Ressourcennutzung.", reasonEn: "Without standardised methodology, third-party risks are assessed inconsistently. Risk-based classification enables efficient resource use.", whenRequired: "Erforderlich als Grundlage des Third-Party-Risikomanagements.", whenRequiredEn: "Required as the foundation of third-party risk management.", sources: ["ISO 27001:2022 A.5.19", "NIST CSF 2.0 GV.SC", "BSI IT-Grundschutz OPS.2.1", "NIS2 Art.21(2)(d)"] },
    { id: "p43-c02", title: "Risikobasierte Sicherheitsanforderungen und Fragebogen-Standardisierung", titleEn: "Risk-Based Security Requirements & Questionnaire Standardisation", description: "Sicherheitsanforderungen an Drittanbieter müssen dem Risiko entsprechen. Kritische Drittanbieter müssen ISO 27001-Zertifizierung oder gleichwertiges nachweisen. Hochrisiko-Drittanbieter müssen detaillierte Sicherheitsfragebögen ausfüllen. Für Standardanbieter genügen grundlegende Sicherheitsvereinbarungen. Wir müssen standardisierte Sicherheitsfragebögen verwenden, angelehnt an internationale Standards (z.B. SIG-Lite, CAIQ). Verschiedene Versionen für unterschiedliche Risikostufen müssen definiert sein. Ergebnisse müssen zentral gespeichert und vergleichbar ausgewertet werden.", descriptionEn: "Security requirements for third parties must match the risk. Critical third parties must demonstrate ISO 27001 certification or equivalent. High-risk third parties must complete detailed security questionnaires. For standard suppliers, basic security agreements suffice. We must use standardised security questionnaires aligned with international standards (e.g., SIG-Lite, CAIQ). Different versions for different risk levels must be defined. Results must be centrally stored and comparatively evaluated.", reason: "Einheitliche Anforderungen für alle Drittanbieter sind ineffizient. Standardisierung ermöglicht wirtschaftlichen Ressourceneinsatz und Vergleichbarkeit.", reasonEn: "Uniform requirements for all third parties are inefficient. Standardisation enables economical resource use and comparability.", whenRequired: "Erforderlich für alle Drittanbieterbeziehungen.", whenRequiredEn: "Required for all third-party relationships.", sources: ["ISO 27001:2022 A.5.19-5.21", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1", "SIG/CAIQ"] },
    { id: "p43-c03", title: "Konzentrationrisiko-Management", titleEn: "Concentration Risk Management", description: "Wir müssen Konzentrationsrisiken bei Drittanbietern identifizieren und steuern. Konzentrationsrisiken entstehen, wenn: ein einzelner Anbieter mehrere kritische Dienste erbringt, viele Anbieter denselben Sub-Dienstleister nutzen oder ein Cloud-Anbieter für die gesamte Infrastruktur verwendet wird. Diversifizierungsstrategien und Contingency-Pläne müssen für identifizierte Konzentrationsrisiken definiert sein.", descriptionEn: "We must identify and manage concentration risks with third parties. Concentration risks arise when: a single provider delivers multiple critical services, many providers use the same sub-service provider, or a cloud provider is used for the entire infrastructure. Diversification strategies and contingency plans must be defined for identified concentration risks.", reason: "Konzentrationsrisiken können dazu führen, dass der Ausfall eines einzigen Drittanbieters die gesamte Organisation lahmlegt.", reasonEn: "Concentration risks can result in the failure of a single third party paralysing the entire organisation.", whenRequired: "Erforderlich als Teil des Risikomanagements.", whenRequiredEn: "Required as part of risk management.", sources: ["NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1", "NIST CSF 2.0 GV.SC"] },
    { id: "p43-c04", title: "Kontinuierliche Bedrohungsüberwachung und automatisierte Bewertung", titleEn: "Continuous Threat Monitoring & Automated Assessment", description: "Wir müssen kontinuierlich Bedrohungsinformationen über unsere Drittanbieter überwachen: öffentlich bekannte Sicherheitsvorfälle, Data Breaches, regulatorische Sanktionen, Finanzprobleme und Cyberrisiko-Ratings von externen Bewertungsdiensten. Automatisierte Plattformen (z.B. SecurityScorecard, BitSight) sollen für die kontinuierliche Risikobewertung genutzt werden. Automatisierte Ratings müssen in das Gesamtrisikobild integriert werden. Verschlechterungen müssen automatisch Eskalationen auslösen und sofortige Maßnahmen einleiten. Compliance-Monitoring (DSGVO, NIS2, branchenspezifisch) ist Teil der kontinuierlichen Überwachung. Für operative SLA-Überwachung und KPI-Management siehe p42-c03.", descriptionEn: "We must continuously monitor threat intelligence about our third parties: publicly known security incidents, data breaches, regulatory sanctions, financial problems, and cyber risk ratings from external assessment services. Automated platforms (e.g., SecurityScorecard, BitSight) should be used for continuous risk assessment. Automated ratings must be integrated into the overall risk picture. Deteriorations must automatically trigger escalations and initiate immediate measures. Compliance monitoring (GDPR, NIS2, sector-specific) is part of continuous monitoring. For operational SLA monitoring and KPI management see p42-c03.", reason: "Jährliche Bewertungen allein sind unzureichend. Automatisierung ermöglicht zeitnahe Risikoerkennung zwischen den Bewertungszyklen.", reasonEn: "Annual assessments alone are insufficient. Automation enables timely risk detection between assessment cycles.", whenRequired: "Empfohlen für kritische Drittanbieter, erforderlich für regulierte Beziehungen.", whenRequiredEn: "Recommended for critical third parties, required for regulated relationships.", sources: ["ISO 27001:2022 A.5.22", "NIST CSF 2.0 GV.SC, DE.CM", "DSGVO Art.28", "NIS2 Art.21(2)(d)"] },
    { id: "p43-c05", title: "Vertragliche SLAs für Sicherheit", titleEn: "Contractual Security SLAs", description: "Für alle kritischen Drittanbieter müssen messbare Sicherheits-SLAs vereinbart werden: maximale Reaktionszeit bei Sicherheitsvorfällen, maximale Ausfallzeit, Patch-Anwendungsfristen, Verfügbarkeitsgarantien, Meldepflichten und Konsequenzen bei Nichteinhaltung. Die Einhaltung der SLAs muss regelmäßig überprüft und berichtet werden. Die operative Messung erfolgt über p42-c03.", descriptionEn: "Measurable security SLAs must be agreed for all critical third parties: maximum response time for security incidents, maximum downtime, patch application deadlines, availability guarantees, notification obligations, and consequences for non-compliance. SLA compliance must be regularly verified and reported. Operational measurement is via p42-c03.", reason: "Ohne messbare SLAs fehlt die Grundlage für die Bewertung der Leistung.", reasonEn: "Without measurable SLAs, the basis for performance evaluation is missing.", whenRequired: "Erforderlich für alle kritischen Drittanbieter.", whenRequiredEn: "Required for all critical third parties.", sources: ["ISO 27001:2022 A.5.20", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p43-c06", title: "Geographische und geopolitische Risiken", titleEn: "Geographical & Geopolitical Risks", description: "Bei der Risikobewertung von Drittanbietern müssen geographische und geopolitische Faktoren berücksichtigt werden: Datenschutzgesetzgebung des Landes, politische Stabilität, Risiko staatlicher Zugriffe auf Daten, Naturkatastrophenrisiko und regulatorische Kompatibilität. Drittanbieter in Hochrisikoländern erfordern zusätzliche Schutzmaßnahmen.", descriptionEn: "Geographical and geopolitical factors must be considered in third-party risk assessment: data protection legislation of the country, political stability, risk of state access to data, natural disaster risk, and regulatory compatibility. Third parties in high-risk countries require additional protective measures.", reason: "Geopolitische Faktoren können den Zugriff auf Daten durch ausländische Behörden oder die Verfügbarkeit von Diensten beeinflussen.", reasonEn: "Geopolitical factors can influence access to data by foreign authorities or availability of services.", whenRequired: "Erforderlich für alle internationalen Drittanbieterbeziehungen.", whenRequiredEn: "Required for all international third-party relationships.", sources: ["DSGVO Art.44-49", "NIS2 Art.21(2)(d)", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p43-c07", title: "Drittanbieter-Notfallplanung", titleEn: "Third-Party Contingency Planning", description: "Für kritische Drittanbieter müssen Notfallpläne definiert sein, die den Ausfall oder die Kompromittierung des Drittanbieters abdecken. Pläne müssen alternative Dienstleister, interne Übernahme-Optionen, minimale Betriebsfähigkeit und Kommunikationsverfahren umfassen. Notfallpläne müssen regelmäßig getestet werden. Exit-Strategien für den operativen Anbieterwechsel werden in p42-c11 definiert.", descriptionEn: "Contingency plans must be defined for critical third parties covering the failure or compromise of the third party. Plans must include alternative service providers, internal takeover options, minimal operational capability, and communication procedures. Contingency plans must be regularly tested. Exit strategies for operational provider change are defined in p42-c11.", reason: "Der Ausfall eines kritischen Drittanbieters kann die Geschäftskontinuität gefährden.", reasonEn: "Failure of a critical third party can jeopardise business continuity.", whenRequired: "Erforderlich für alle kritischen Drittanbieter.", whenRequiredEn: "Required for all critical third parties.", sources: ["ISO 27001:2022 A.5.29", "NIS2 Art.21(2)(c)", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p43-c08", title: "Risikodashboard und Berichterstattung", titleEn: "Risk Dashboard & Reporting", description: "Wir müssen ein zentrales Dashboard für Drittanbieterrisiken führen, das den aktuellen Risikostatus aller kritischen und hochriskanten Drittanbieter zeigt. Das Dashboard muss Risikotrends, offene Maßnahmen, bevorstehende Bewertungen und aktuelle Vorfälle aggregiert darstellen. Drittanbieterrisiken müssen regelmäßig an die Geschäftsleitung und relevante Stakeholder berichtet werden. Berichte müssen Gesamtrisikostatus, Top-Risiken, Trendentwicklung, offene Maßnahmen und Empfehlungen enthalten. Bei kritischen Risikoveränderungen muss eine Ad-hoc-Berichterstattung erfolgen.", descriptionEn: "We must maintain a central dashboard for third-party risks showing the current risk status of all critical and high-risk third parties. The dashboard must show aggregated risk trends, open actions, upcoming assessments, and current incidents. Third-party risks must be regularly reported to executive management and relevant stakeholders. Reports must contain overall risk status, top risks, trend development, open measures, and recommendations. Ad-hoc reporting must occur for critical risk changes.", reason: "Ohne aggregierte Sicht und transparente Berichterstattung können Drittanbieterrisiken nicht auf Führungsebene gesteuert werden.", reasonEn: "Without aggregated view and transparent reporting, third-party risks cannot be managed at leadership level.", whenRequired: "Empfohlen für Organisationen mit vielen Drittanbieterbeziehungen.", whenRequiredEn: "Recommended for organisations with many third-party relationships.", sources: ["ISO 27001:2022 §9.3", "NIS2 Art.20(1)", "NIST CSF 2.0 GV.SC, GV.RM"] },
    { id: "p43-c09", title: "DORA-Konformität für Finanzsektor-Drittanbieter", titleEn: "DORA Compliance for Financial Sector Third Parties", description: "Für Organisationen im Finanzsektor oder mit Finanzsektor-Kunden müssen die Anforderungen des Digital Operational Resilience Act (DORA) an IKT-Drittanbieter erfüllt werden. Dies umfasst: erweiterte Vertragsinhalte, Meldepflichten an die Aufsichtsbehörde, Ausstiegsstrategien und Konzentrationsrisiko-Management für kritische IKT-Drittanbieter.", descriptionEn: "For organisations in the financial sector or with financial sector customers, the requirements of the Digital Operational Resilience Act (DORA) for ICT third-party providers must be met. This includes: extended contract content, reporting obligations to supervisory authorities, exit strategies, and concentration risk management for critical ICT third-party providers.", reason: "DORA stellt spezifische, strenge Anforderungen an das Management von IKT-Drittanbietern im Finanzsektor.", reasonEn: "DORA establishes specific, strict requirements for management of ICT third-party providers in the financial sector.", whenRequired: "Erforderlich für Organisationen im Finanzsektor.", whenRequiredEn: "Required for organisations in the financial sector.", sources: ["DORA Art.28-44", "NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.19-5.22"] },
    { id: "p43-c10", title: "Überprüfung des Third-Party-Risikomanagements", titleEn: "Review of Third-Party Risk Management", description: "Das Third-Party-Risikomanagement-Programm muss mindestens jährlich überprüft und aktualisiert werden. Die Überprüfung muss die Wirksamkeit des Programms, Erfahrungen aus Vorfällen, neue regulatorische Anforderungen und Veränderungen im Drittanbieterportfolio berücksichtigen. Die Überprüfung muss mit der Lieferantensicherheitsrichtlinie (p42-c16) koordiniert werden.", descriptionEn: "The third-party risk management programme must be reviewed and updated at least annually. The review must consider programme effectiveness, incident experiences, new regulatory requirements, and changes in the third-party portfolio. The review must be coordinated with the supplier security policy (p42-c16).", reason: "Ein statisches Risikomanagement-Programm wird zunehmend unwirksam.", reasonEn: "A static risk management programme becomes increasingly ineffective.", whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.", whenRequiredEn: "Always required as part of the ISMS cycle.", sources: ["ISO 27001:2022 §10.1-10.2", "NIS2 Art.21", "NIST CSF 2.0 GV.SC"] },
    { id: "p43-c11", title: "Datenschutz-Due-Diligence für Auftragsverarbeiter", titleEn: "Data Protection Due Diligence for Processors", description: "Für Auftragsverarbeiter gemäß DSGVO Art.28 muss eine spezifische Datenschutz-Due-Diligence durchgeführt werden. Bewertungskriterien: TOM-Nachweis, Datenschutzbeauftragter, Verarbeitungsverzeichnis, Sub-Auftragsverarbeiter-Management, Benachrichtigungspflichten bei Datenpannen und Datenresidenz. Wir müssen sicherstellen, dass personenbezogene Daten in der gesamten Lieferkette DSGVO-konform verarbeitet werden. Auftragsverarbeitungsverträge müssen mit allen relevanten Lieferanten abgeschlossen werden.", descriptionEn: "Specific data protection due diligence must be conducted for processors per GDPR Art.28. Assessment criteria: TOM evidence, data protection officer, processing records, sub-processor management, breach notification obligations, and data residency. We must ensure personal data is processed GDPR-compliantly throughout the supply chain. Data processing agreements must be concluded with all relevant suppliers.", reason: "Wir bleiben als Verantwortlicher für die Auswahl geeigneter Auftragsverarbeiter verantwortlich. DSGVO-Verstöße in der Lieferkette können zu erheblichen Bußgeldern führen.", reasonEn: "We remain responsible as controller for selecting suitable processors. GDPR violations in the supply chain can lead to significant fines.", whenRequired: "Erforderlich für alle Auftragsverarbeitungsbeziehungen.", whenRequiredEn: "Required for all data processing relationships.", sources: ["DSGVO Art.28, Art.32, Art.44-49", "ISO 27001:2022 A.5.34", "BSI IT-Grundschutz CON.2", "NIS2 Art.21(2)(d)"] },
    { id: "p43-c12", title: "Exit-Strategie und Anbieterwechsel", titleEn: "Exit Strategy & Provider Transition", description: "Für jeden kritischen Drittanbieter muss eine dokumentierte Exit-Strategie vorliegen, die den geordneten Übergang zu einem Alternativanbieter oder die Insourcing-Option beschreibt. Die Strategie muss umfassen: Datenrückgabe und -löschung beim bisherigen Anbieter, Migrationszeitplan und -ressourcen, Übergangsphase mit parallelem Betrieb, vertragliche Kündigungsfristen und -bedingungen sowie Mindestanforderungen an den Nachfolgeanbieter. Exit-Strategien müssen mindestens jährlich auf Durchführbarkeit geprüft werden.", descriptionEn: "For each critical third party, a documented exit strategy must exist describing the orderly transition to an alternative provider or insourcing option. The strategy must include: data return and deletion at the current provider, migration timeline and resources, transition phase with parallel operation, contractual termination periods and conditions, and minimum requirements for the successor provider. Exit strategies must be tested for feasibility at least annually.", reason: "Ohne vorbereitete Exit-Strategie ist die Organisation bei Anbieterausfall oder -kündigung handlungsunfähig und riskiert Datenverlust oder Betriebsunterbrechung.", reasonEn: "Without a prepared exit strategy, we are unable to act in case of provider failure or termination and risk data loss or operational disruption.", whenRequired: "Erforderlich für alle kritischen Drittanbieter.", whenRequiredEn: "Required for all critical third parties.", sources: ["NIS2 Art.21(2)(d)", "DORA Art.28(8)", "ISO 27001:2022 A.5.20", "BSI IT-Grundschutz OPS.2.1"] },
    { id: "p43-c13", title: "Fourth-Party-Risikomanagement", titleEn: "Fourth-Party Risk Management", description: "Wir müssen die Unterauftragnehmer (Fourth Parties) ihrer kritischen Drittanbieter identifizieren und bewerten. Vertragliche Regelungen müssen sicherstellen, dass Drittanbieter die Nutzung von Unterauftragnehmern offenlegen und genehmigen lassen. Wesentliche Änderungen in der Unterauftragnehmerkette müssen der Organisation gemeldet werden. Das Risiko kaskadierender Abhängigkeiten durch gemeinsame Fourth Parties muss analysiert und gesteuert werden.", descriptionEn: "We must identify and assess sub-contractors (fourth parties) of their critical third parties. Contractual provisions must ensure third parties disclose and seek approval for use of sub-contractors. Material changes in the sub-contractor chain must be reported to the organisation. The risk of cascading dependencies through shared fourth parties must be analysed and managed.", reason: "Sicherheitsvorfälle bei Unterauftragnehmern können die gesamte Lieferkette kompromittieren. Ohne Transparenz über Fourth Parties bleiben blinde Flecken im Risikobild.", reasonEn: "Security incidents at sub-contractors can compromise the entire supply chain. Without transparency about fourth parties, blind spots remain in the risk picture.", whenRequired: "Erforderlich für kritische und hochriskante Drittanbieter.", whenRequiredEn: "Required for critical and high-risk third parties.", sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.5.21", "NIST CSF 2.0 GV.SC", "DORA Art.29"] },
    { id: "p43-c14", title: "Vorfallkoordination mit Drittanbietern", titleEn: "Incident Coordination with Third Parties", description: "Wir müssen Verfahren für die koordinierte Vorfallbehandlung mit Drittanbietern definieren. Dies umfasst: gemeinsame Eskalationsprozesse, definierte Kommunikationskanäle für Notfälle, gemeinsame Forensik-Verfahren bei Lieferketten-Vorfällen, koordinierte Meldepflichten gegenüber Behörden und abgestimmte Kommunikation gegenüber betroffenen Kunden. Regelmäßige gemeinsame Übungen mit kritischen Drittanbietern müssen durchgeführt werden. Die interne Incident-Response-Logik wird in p30-p33 geregelt.", descriptionEn: "We must define procedures for coordinated incident handling with third parties. This includes: joint escalation processes, defined communication channels for emergencies, joint forensic procedures for supply chain incidents, coordinated reporting obligations to authorities, and aligned communication to affected customers. Regular joint exercises with critical third parties must be conducted. Internal incident response logic is governed in p30-p33.", reason: "Lieferketten-Vorfälle erfordern koordiniertes Handeln zwischen Organisation und Drittanbieter. Ohne vorab definierte Koordination geht wertvolle Reaktionszeit verloren.", reasonEn: "Supply chain incidents require coordinated action between organisation and third party. Without pre-defined coordination, valuable response time is lost.", whenRequired: "Erforderlich für alle kritischen Drittanbieter.", whenRequiredEn: "Required for all critical third parties.", sources: ["NIS2 Art.21(2)(d)", "NIS2 Art.23", "ISO 27001:2022 A.5.24-A.5.26", "BSI IT-Grundschutz DER.2.1"] },
    { id: "p43-c15", title: "Regulatorische Änderungen und Anpassungspflicht", titleEn: "Regulatory Changes & Adaptation Obligation", description: "Wir müssen regulatorische Änderungen, die Drittanbieterbeziehungen betreffen, systematisch überwachen und bewerten — neue NIS2-Durchführungsrechtsakte, DSGVO-Leitlinien, DORA-Anforderungen, nationale Umsetzungsgesetze und branchenspezifische Vorgaben. Bei relevanten Änderungen müssen bestehende Verträge, Risikobewertungen und Überwachungsprozesse innerhalb definierter Fristen angepasst werden. Die Verantwortlichkeit für das regulatorische Monitoring muss klar zugewiesen sein.", descriptionEn: "We must systematically monitor and assess regulatory changes affecting third-party relationships — new NIS2 implementing acts, GDPR guidelines, DORA requirements, national transposition laws, and sector-specific requirements. For relevant changes, existing contracts, risk assessments, and monitoring processes must be adapted within defined deadlines. Responsibility for regulatory monitoring must be clearly assigned.", reason: "Die regulatorische Landschaft für Lieferkettensicherheit entwickelt sich dynamisch. Ohne systematisches Monitoring riskiert die Organisation Non-Compliance.", reasonEn: "The regulatory landscape for supply chain security is evolving dynamically. Without systematic monitoring, we risk non-compliance.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["NIS2 Art.21(2)(d)", "DORA Art.28", "DSGVO Art.28", "ISO 27001:2022 A.5.31"] },
    { id: "p43-c16", title: "Überprüfung des Third-Party-Risikomanagements", titleEn: "Review of Third-Party Risk Management", description: "Das Third-Party-Risikomanagement-Programm muss mindestens jährlich überprüft und aktualisiert werden. Die Überprüfung muss die Wirksamkeit des Programms, Erfahrungen aus Vorfällen, neue regulatorische Anforderungen und Veränderungen im Drittanbieterportfolio berücksichtigen. Die Überprüfung muss mit der Lieferantensicherheitsrichtlinie (p42-c16) koordiniert werden.", descriptionEn: "The third-party risk management programme must be reviewed and updated at least annually. The review must consider programme effectiveness, incident experiences, new regulatory requirements, and changes in the third-party portfolio. The review must be coordinated with the supplier security policy (p42-c16).", reason: "Ein statisches Risikomanagement-Programm wird zunehmend unwirksam.", reasonEn: "A static risk management programme becomes increasingly ineffective.", whenRequired: "Immer erforderlich als Teil des ISMS-Regelkreises.", whenRequiredEn: "Always required as part of the ISMS cycle.", sources: ["ISO 27001:2022 §10.1-10.2", "NIS2 Art.21", "NIST CSF 2.0 GV.SC"] },
  ],
};
